<script lang="ts">
  import { getCalendarToday, getCalendarValueDate, type CalendarCell, type CalendarDate, type CalendarPanel, type CalendarRange, type CalendarValue, type CalendarWeekday } from '@fex/components-core/calendar'
  import { createDatePickerDisabledDate } from '@fex/components-core/date-picker/constraints'
  import { getDefaultPanelByPicker, getGranularityByPicker, getRangePanelViewDates } from '@fex/components-core/date-picker/panel'
  import { createNextRangeValue, getRangeFromValue } from '@fex/components-core/date-picker/range'
  import { formatDatePickerValue, normalizeDatePickerValue, parseDatePickerValue } from '@fex/components-core/date-picker/value'
  import type { DatePickerInputPart, DatePickerPicker } from '@fex/components-core/date-picker/types'
  import { datePickerCellClassName, datePickerContentClassName, datePickerFooterClassName, datePickerGridClassName, datePickerHeaderClassName, datePickerHeaderLabelClassName, datePickerHeaderNavigationClassName, datePickerPanelClassName, datePickerPanelsClassName, datePickerRangeInputClassName, datePickerWeekHeaderClassName } from '@fex/components-styles/date-picker'
  import CalendarIcon from '../../icon/calendar.svelte'
  import ChevronLeftIcon from '../../icon/chevron-left.svelte'
  import ChevronRightIcon from '../../icon/chevron-right.svelte'
  import Button from '../../ui/button/button.svelte'
  import CalendarCellView from '../calendar/calendar-cell.svelte'
  import CalendarGrid from '../calendar/calendar-grid.svelte'
  import CalendarHeader from '../calendar/calendar-header.svelte'
  import CalendarRoot from '../calendar/calendar.svelte'
  import CalendarWeekHeader from '../calendar/calendar-week-header.svelte'
  import InputClear from '../input/input-clear.svelte'
  import InputControl from '../input/input-control.svelte'
  import InputRoot from '../input/input-root.svelte'
  import InputSuffix from '../input/input-suffix.svelte'
  import Popover from '../popover/popover.svelte'
  import PopoverContent from '../popover/popover-content.svelte'
  import PopoverPortal from '../popover/popover-portal.svelte'
  import PopoverTrigger from '../popover/popover-trigger.svelte'
  interface Props { class?: string | undefined; value?: CalendarRange<CalendarValue> | undefined; defaultValue?: CalendarRange<CalendarValue> | undefined; open?: boolean | undefined; defaultOpen?: boolean | undefined; picker?: DatePickerPicker | undefined; needConfirm?: boolean | undefined; disabled?: boolean | undefined; readOnly?: boolean | undefined; allowEmpty?: boolean | { start?: boolean; end?: boolean } | undefined; allowClear?: boolean | undefined; order?: boolean | undefined; panelCount?: 1 | 2 | undefined; minDate?: CalendarDate | undefined; maxDate?: CalendarDate | undefined; weekStartsOn?: CalendarWeekday | undefined; disabledDate?: ((date: CalendarDate, part: DatePickerInputPart) => boolean) | undefined; onChange?: ((value: CalendarRange<CalendarValue>) => void) | undefined; onOpenChange?: ((open: boolean) => void) | undefined }
  let { class: className, value, defaultValue, open, defaultOpen = false, picker = 'date', needConfirm = false, disabled = false, readOnly = false, allowEmpty = false, allowClear = true, order = true, panelCount = 2, minDate, maxDate, weekStartsOn = 0, disabledDate: disabledDateProp, onChange, onOpenChange }: Props = $props()
  let localValue = $state<CalendarRange<CalendarValue>>(defaultValue ?? {})
  let localOpen = $state(defaultOpen)
  let pending = $state<CalendarRange<CalendarValue>>(localValue)
  let activePart = $state<DatePickerInputPart>('start')
  let focusedPart = $state<DatePickerInputPart | null>(null)
  let currentPanel = $state<CalendarPanel>(getDefaultPanelByPicker(picker))
  let currentViewDate = $state(getCalendarToday())
  const currentValue = $derived(value ?? localValue)
  const activeValue = $derived(needConfirm ? pending : currentValue)
  const dates = $derived(getRangePanelViewDates(currentViewDate, currentPanel))
  const visibleDates = $derived(panelCount === 1 || (picker !== 'date' && picker !== 'week') ? [dates[0]] : dates)
  const startText = $derived(formatDatePickerValue(currentValue.start ?? null, { picker, weekStartsOn }))
  const endText = $derived(formatDatePickerValue(currentValue.end ?? null, { picker, weekStartsOn }))
  const hasValue = $derived(Boolean(startText || endText))
  function setOpen(next: boolean) { if (open === undefined) localOpen = next; if (next) pending = currentValue; if (!next) { currentPanel = getDefaultPanelByPicker(picker); focusedPart = null }; onOpenChange?.(next) }
  function close() { setOpen(false) }
  function commit(next: CalendarRange<CalendarValue>) { if (value === undefined) localValue = next; onChange?.(next) }
  function clear() { const allowed = allowEmpty === true ? { start: true, end: true } : typeof allowEmpty === 'object' ? allowEmpty : {}; const current = activeValue; const next: CalendarRange<CalendarValue> = {}; if (!allowed.start && current.start) next.start = current.start; if (!allowed.end && current.end) next.end = current.end; pending = next; commit(next) }
  function select(cell: CalendarCell) { const date = getCalendarValueDate(cell.value); currentViewDate = date; if (cell.panel === 'year' && picker !== 'year') { currentPanel = picker === 'month' || picker === 'quarter' ? getDefaultPanelByPicker(picker) : 'month'; return }; if (cell.panel === 'month' && picker !== 'month') { currentPanel = 'date'; return }; const next = createNextRangeValue(activeValue, normalizeDatePickerValue(date, picker, weekStartsOn), activePart, order); if (needConfirm) pending = next; else commit(next); if (activePart === 'start') { activePart = 'end'; focusedPart = 'end' } else if (next.start && next.end && !needConfirm) close() }
  function focus(part: DatePickerInputPart) { activePart = part; focusedPart = part }
  function input(part: DatePickerInputPart, text: string) { focus(part); const parsed = parseDatePickerValue(text, { picker, weekStartsOn }); if (!parsed.valid) return; const next = createNextRangeValue(activeValue, parsed.value, part, order); if (needConfirm) pending = next; else commit(next) }
  function isDisabled(date: CalendarDate) { return createDatePickerDisabledDate({ picker, panel: currentPanel, ...(minDate ? { minDate } : {}), ...(maxDate ? { maxDate } : {}), ...(disabledDateProp ? { disabledDate: current => Boolean(disabledDateProp?.(current, activePart)) } : {}) })(date, { activePart, from: getRangeFromValue(activeValue, activePart), rangeValue: activeValue }) }
</script>
<Popover open={open ?? localOpen} trigger={disabled ? [] : ['focus', 'click']} onOpenChange={setOpen}><PopoverTrigger>{#snippet children(slot)}<div use:slot.action role="button" tabindex={disabled ? -1 : 0} aria-disabled={disabled || undefined} class={className} onclick={event => { if (!disabled) slot.props.onclick?.(event as never) }} onkeydown={event => { if (!disabled && (event.key === 'Enter' || event.key === ' ')) slot.props.onclick?.(event as never) }}><InputRoot value={startText + endText} {disabled} {readOnly} class="cursor-pointer gap-0" onClear={clear}><InputRoot data-range-part="start" data-active={focusedPart === 'start' || undefined} value={startText} {readOnly} class={datePickerRangeInputClassName} onValueChange={text => input('start', text)}><InputControl class="min-w-0 px-2 text-center" placeholder="开始日期" onfocus={() => focus('start')} onclick={event => { event.stopPropagation(); if (!disabled) setOpen(true); focus('start') }} /></InputRoot><span aria-hidden="true" class="inline-flex shrink-0 items-center justify-center px-1 text-muted-foreground">→</span><InputRoot data-range-part="end" data-active={focusedPart === 'end' || undefined} value={endText} {readOnly} class={datePickerRangeInputClassName} onValueChange={text => input('end', text)}><InputControl class="min-w-0 px-2 text-center" placeholder="结束日期" onfocus={() => focus('end')} onclick={event => { event.stopPropagation(); if (!disabled) setOpen(true); focus('end') }} /></InputRoot>{#if allowClear}<InputClear />{/if}{#if !allowClear || !hasValue}<InputSuffix><CalendarIcon /></InputSuffix>{/if}</InputRoot></div>{/snippet}</PopoverTrigger><PopoverPortal><PopoverContent class={datePickerContentClassName}><div class={datePickerPanelsClassName}>{#each visibleDates as panelDate, index (`${panelDate.year}-${panelDate.month}-${index}`)}<CalendarRoot class={datePickerPanelClassName} range={activeValue} viewDate={panelDate} panel={currentPanel} granularity={getGranularityByPicker(picker)} {weekStartsOn} disabledDate={isDisabled} onCellSelect={select} onPanelChange={next => currentPanel = next}><CalendarHeader>{#snippet children(header)}{@const datePanel = header.panel === 'date'}{@const yearPanel = header.panel === 'year' || header.panel === 'decade'}{@const step = yearPanel ? 10 : 1}<div class={datePickerHeaderClassName}><div class="flex items-center gap-1"><Button variant="ghost" size="icon-sm" class={datePickerHeaderNavigationClassName} onclick={() => currentViewDate = { ...header.viewDate, year: header.viewDate.year - step }}><ChevronLeftIcon /><ChevronLeftIcon class="-ml-2" /></Button>{#if datePanel}<Button variant="ghost" size="icon-sm" class={datePickerHeaderNavigationClassName} onclick={header.previousMonth}><ChevronLeftIcon /></Button>{/if}</div><div class="flex items-center gap-2 text-base font-semibold"><Button variant="ghost" size="sm" class={datePickerHeaderLabelClassName} onclick={() => header.setPanel('year')}>{header.panel === 'decade' ? `${Math.floor(header.viewDate.year / 10) * 10}-${Math.floor(header.viewDate.year / 10) * 10 + 9}年` : `${header.viewDate.year}年`}</Button>{#if picker !== 'year' && datePanel}<Button variant="ghost" size="sm" class={datePickerHeaderLabelClassName} onclick={() => header.setPanel('month')}>{header.viewDate.month}月</Button>{/if}</div><div class="flex items-center gap-1">{#if datePanel}<Button variant="ghost" size="icon-sm" class={datePickerHeaderNavigationClassName} onclick={header.nextMonth}><ChevronRightIcon /></Button>{/if}<Button variant="ghost" size="icon-sm" class={datePickerHeaderNavigationClassName} onclick={() => currentViewDate = { ...header.viewDate, year: header.viewDate.year + step }}><ChevronRightIcon /><ChevronRightIcon class="-ml-2" /></Button></div></div>{/snippet}</CalendarHeader>{#if currentPanel === 'date'}<CalendarWeekHeader class={datePickerWeekHeaderClassName} />{/if}<CalendarGrid class={datePickerGridClassName} data-panel={currentPanel}>{#snippet children(cell)}<CalendarCellView {cell} class={datePickerCellClassName}>{cell.label}</CalendarCellView>{/snippet}</CalendarGrid></CalendarRoot>{/each}</div>{#if needConfirm}<div class={datePickerFooterClassName}><Button type="button" variant="outline" onclick={() => { pending = currentValue; close() }}>取消</Button><Button type="button" onclick={() => { commit(pending); close() }}>确认</Button></div>{/if}</PopoverContent></PopoverPortal></Popover>
